func testAlertasToManyAddOpAltAlertaItens(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Alertas
	var b, c, d, e AlertaIten

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, alertasDBTypes, false, strmangle.SetComplement(alertasPrimaryKeyColumns, alertasColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AlertaIten{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, alertaItenDBTypes, false, strmangle.SetComplement(alertaItenPrimaryKeyColumns, alertaItenColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*AlertaIten{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddAltAlertaItens(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.AltID != first.AltID {
			t.Error("foreign key was wrong value", a.AltID, first.AltID)
		}
		if a.AltID != second.AltID {
			t.Error("foreign key was wrong value", a.AltID, second.AltID)
		}

		if first.R.Alt != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Alt != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.AltAlertaItens[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.AltAlertaItens[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.AltAlertaItens().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
